// A layer-only layout groups by technology; a single change then rebuilds a
// shared module that every feature compiles against:
// include(":ui")
// include(":domain")
// include(":data")

// :core:data:api — interfaces and models only; no Retrofit, no Room
interface UserRepository {
    fun observeUser(): Flow<User?>
}

// :core:data:impl — the implementation, kept off every consumer's classpath
class DefaultUserRepository(
    private val dao: UserDao,
    private val api: UserApi,
) : UserRepository

// :app — the only place that knows the concrete type
@Module
@InstallIn(SingletonComponent::class)
abstract class DataBindingModule {
    @Binds
    abstract fun bindUserRepository(impl: DefaultUserRepository): UserRepository
}

// build-logic/convention/build.gradle.kts
plugins {
