// build-logic/convention/src/main/kotlin/MyAppLibraryPlugin.kt
class MyAppLibraryPlugin : Plugin<Project> {
    override fun apply(target: Project) = with(target) {
        pluginManager.apply("com.android.library")
        extensions.configure<LibraryExtension> {
            compileSdk = 36
            defaultConfig { minSdk = 24 }
            buildFeatures { buildConfig = true }
        }
    }
}

// Any module then declares:  plugins { id("myapp.android.library") }

// :core:data:api/build.gradle.kts
dependencies {
    // Flow appears in the public ABI, so it is promoted to api.
    api(libs.kotlinx.coroutines.core)
    // Gson is an implementation detail, invisible to consumers.
    implementation(libs.gson)
}

// The public interface is the surface; supporting types are internal
interface UserRepository {
    fun observeUser(): Flow<User?>
}

