// The one seam every feature sees — injected, faked in tests
interface FeatureFlagProvider {
    fun isEnabled(flag: FeatureFlag): Boolean
}

enum class FeatureFlag(val default: Boolean, val owner: String, val removeBy: String) {
    NEW_CHECKOUT(false, "payments", "2026-12-01"),
    EXPERIMENT_RANKING(false, "growth", "2026-10-01"),
    KILL_SWITCH_NEW_SYNC(true, "platform", ""),
}

enum class CheckoutMode { NEW, LEGACY }

@HiltViewModel
class CheckoutViewModel @Inject constructor(
    private val flags: FeatureFlagProvider,
) : ViewModel() {
    fun mode(): CheckoutMode =
        if (flags.isEnabled(FeatureFlag.NEW_CHECKOUT)) CheckoutMode.NEW else CheckoutMode.LEGACY
}

