// Each region owns its loading/error/data state and tests in isolation
data class StatsUiState(
    val sessions: ImmutableList<Session> = persistentListOf(),
    val isRefreshing: Boolean = false,
)

@HiltViewModel
class StatsViewModel @Inject constructor(
    private val observeStats: ObserveStatsUseCase,
) : ViewModel() {
    private val _state = MutableStateFlow(StatsUiState())
    val state: StateFlow<StatsUiState> = _state.asStateFlow()
}

@Module
@InstallIn(SingletonComponent::class)
object DispatchersModule {
    @Provides @IoDispatcher
    fun io(): CoroutineDispatcher = Dispatchers.IO

    @Provides @DefaultDispatcher
    fun default(): CoroutineDispatcher = Dispatchers.Default
}

class ArticleRepository @Inject constructor(
    private val api: ArticleApi,
    private val dao: ArticleDao,
    @IoDispatcher private val io: CoroutineDispatcher,
) {
    // The thread boundary lives here; callers stay main-safe
    suspend fun refresh() = withContext(io) {
        val latest = api.fetchArticles()
        dao.upsertAll(latest)
    }

    fun observeArticles(): Flow<List<Article>> = dao.observeAll().flowOn(io)
}

// Testable: dependency injected, logic pure Kotlin — no Android runtime needed
class CheckoutCalculator(private val taxRate: Double) {
    fun total(itemCosts: List<Double>): Double =
        itemCosts.sum() * (1 + taxRate)
}

// Plain JVM test: instant, deterministic, no Robolectric
class CheckoutCalculatorTest {
    @Test
    fun `adds tax to the item total`() {
        assertEquals(11.0, CheckoutCalculator(0.1).total(listOf(10.0)))
    }
}

// Step 1: wrap the legacy path behind a clean interface
interface ProfileDataSource {
    suspend fun getProfile(): Profile?
}

// Anti-corruption layer: translates legacy storage shapes into the domain model
class LegacyProfileDataSource(
    private val prefs: SharedPreferences,
    private val parser: LegacyProfileParser,
) : ProfileDataSource {
    override suspend fun getProfile(): Profile? {
        val raw = prefs.getString(KEY_PROFILE, null) ?: return null
        return parser.parse(raw)
    }
}
